void VSubrevF32Vop2::execute_impl(amdgpu::Wavefront &wf) {
  if (inst_.src0 == amdgpu::SRC_DPP)
    amdgpu::dpp::apply_dpp(src_operands_[0], dpp_ctrl_, dpp_row_mask_, dpp_bank_mask_,
                           dpp_bound_ctrl_, dpp_fi_, dpp_src0_, wf);
  if (amdgpu::dpp::is_src_dpp8(inst_.src0))
    amdgpu::dpp::apply_dpp8(src_operands_[0], dpp8_lane_sel_, dpp_fi_, dpp_src0_, wf);
  if (inst_.src0 == amdgpu::SRC_SDWA) {
    uint32_t ws = wf.wf_size();
    if (sdwa_src0_sel_ != amdgpu::sdwa::DWORD) {
      uint64_t ex = wf.exec();
      auto src0_view = amdgpu::RegisterAccess(wf).read_operand(
          *src_operands_[0], ex, amdgpu::sdwa::sdwa_src_byte_mask(sdwa_src0_sel_));
      uint32_t result[64] = {};
      for (uint32_t i = 0; i < ws; ++i) {
        if (!(ex & (1ULL << i)))
          continue;
        result[i] =
            amdgpu::sdwa::sdwa_src_select(src0_view.lane(i), sdwa_src0_sel_, sdwa_src0_sext_);
      }
      if (sdwa_src0_abs_ || sdwa_src0_neg_) {
        for (uint32_t i = 0; i < ws; ++i) {
          float sv = std::bit_cast<float>(result[i]);
          if (sdwa_src0_abs_)
            sv = std::fabs(sv);
          if (sdwa_src0_neg_)
            sv = -sv;
          result[i] = std::bit_cast<uint32_t>(sv);
        }
      }
      dpp_src0_ = std::make_unique<DppOperand>(*src_operands_[0], result, static_cast<int>(ws));
    }
    if (sdwa_src1_sel_ != amdgpu::sdwa::DWORD && num_src_ > 1) {
      uint64_t ex = wf.exec();
      auto src1_view = amdgpu::RegisterAccess(wf).read_operand(
          vsrc1, ex, amdgpu::sdwa::sdwa_src_byte_mask(sdwa_src1_sel_));
      uint32_t result1[64] = {};
      for (uint32_t i = 0; i < ws; ++i) {
        if (!(ex & (1ULL << i)))
          continue;
        result1[i] =
            amdgpu::sdwa::sdwa_src_select(src1_view.lane(i), sdwa_src1_sel_, sdwa_src1_sext_);
      }
      if (sdwa_src1_abs_ || sdwa_src1_neg_) {
        for (uint32_t i = 0; i < ws; ++i) {
          float sv = std::bit_cast<float>(result1[i]);
          if (sdwa_src1_abs_)
            sv = std::fabs(sv);
          if (sdwa_src1_neg_)
            sv = -sv;
          result1[i] = std::bit_cast<uint32_t>(sv);
        }
      }
      dpp_src1_ = std::make_unique<DppOperand>(vsrc1, result1, static_cast<int>(ws));
    }
  }
  if (dpp_src0_)
    src0.set_delegate(dpp_src0_.get());
  if (dpp_src1_)
    vsrc1.set_delegate(dpp_src1_.get());
  amdgpu::execute_v_subrev_f32_vop2(*this, wf);
  src0.clear_delegate();
  vsrc1.clear_delegate();
}

VMacLegacyF32Vop2::VMacLegacyF32Vop2(const MachineInst *inst)
    : Vop2("v_mac_legacy_f32_e32", reinterpret_cast<const OpEncoding *>(inst),
           make_exec_fn<VMacLegacyF32Vop2>()),
      vdst(32, OperandType::OPR_VGPR, reinterpret_cast<const OpEncoding *>(inst)->vdst),
      src0(32, OperandType::OPR_SRC, reinterpret_cast<const OpEncoding *>(inst)->src0),
      vsrc1(32, OperandType::OPR_VGPR, reinterpret_cast<const OpEncoding *>(inst)->vsrc1) {
  src_operands_[0] = &vdst;
  dst_operands_[0] = &vdst;
  src_operands_[1] = &src0;
  src_operands_[2] = &vsrc1;
  num_src_ = 3;
  num_dst_ = 1;
  if (reinterpret_cast<const OpEncoding *>(inst)->src0 == 255)
    src0 = Operand(
        32, OperandType::OPR_SIMM32,
        static_cast<int>(reinterpret_cast<const Vop2InstLiteralMachineInst *>(inst)->simm32));
  if (reinterpret_cast<const OpEncoding *>(inst)->src0 == amdgpu::SRC_DPP ||
      amdgpu::dpp::is_src_dpp8(reinterpret_cast<const OpEncoding *>(inst)->src0))
    throw util::InvalidInst("V_MAC_LEGACY_F32 does not support DPP", "");
  if (reinterpret_cast<const OpEncoding *>(inst)->src0 == amdgpu::SRC_SDWA)
    throw util::InvalidInst("V_MAC_LEGACY_F32 does not support SDWA", "");
}

void VMacLegacyF32Vop2::execute_impl(amdgpu::Wavefront &wf) {
  uint64_t exec = wf.exec();
  for (uint32_t lane = 0; lane < wf.wf_size(); ++lane) {
    if (!(exec & (1ULL << lane)))
      continue;
    amdgpu::sdwa::write_lane<true>(
        *this, wf, vdst, lane,
        std::bit_cast<uint32_t>(
            std::fma(std::bit_cast<float>(amdgpu::RegisterAccess(wf).read_lane(src0, lane)),
                     std::bit_cast<float>(amdgpu::RegisterAccess(wf).read_lane(vsrc1, lane)),
                     std::bit_cast<float>(amdgpu::RegisterAccess(wf).read_lane(vdst, lane)))));
  }
}

